import React, { useState } from "react";

export default function InfoSection({ title = "Understanding", items = [], compact = false }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ maxWidth: compact ? 'min(900px, 90vw)' : 900, margin: '30px auto', padding: 0, width: compact ? 'fit-content' : '100%' }}>
      <button
        onClick={() => setOpen(!open)}
        style={{
          width: '100%',
          textAlign: 'left',
          background: 'rgba(124,58,237,0.18)',
          border: '1px solid rgba(124,58,237,0.45)',
          borderRadius: 12,
          padding: '14px 18px',
          color: '#e5e7eb',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 10,
          cursor: 'pointer'
        }}
      >
        <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          {/* Question mark in a circle */}
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <circle cx="12" cy="12" r="10" stroke="#a78bfa" strokeWidth="2" />
            <path d="M9.5 9.5C9.5 8 10.7 7 12.2 7C13.7 7 14.8 8.1 14.8 9.3C14.8 10.5 14.2 11 13.3 11.6C12.4 12.1 12.2 12.6 12.2 13.5" stroke="#a78bfa" strokeWidth="2" strokeLinecap="round" />
            <circle cx="12.2" cy="16.5" r="1" fill="#a78bfa" />
          </svg>
          <span style={{ fontWeight: 700, color: '#a78bfa' }}>{title}</span>
        </span>
        <span style={{ color: '#a78bfa' }}>{open ? '−' : '+'}</span>
      </button>
      {open && (
        <div
          style={{
            marginTop: 12,
            background: 'rgba(17,24,39,0.6)',
            border: '1px solid rgba(124,58,237,0.35)',
            borderRadius: 12,
            padding: 18,
          }}
        >
          {items.map((it, idx) => (
            <div key={idx} style={{ marginBottom: 16 }}>
              <div style={{ fontWeight: 700, color: it.color || '#fbbf24', marginBottom: 6 }}>{it.heading}</div>
              <div style={{ color: '#d1d5db', lineHeight: 1.6 }}>{it.content}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

