import React, { useEffect, useMemo, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { motion } from "framer-motion";
import { Button, Card, CardContent } from "../LandingPage";
import { useAccount } from "wagmi";
import { PauseCircle, PlayCircle, UserPlus, UserMinus, ListCheck } from "lucide-react";
import MycelialTitle from "../MycelialTitle";
import GearIcon from "../icons/GearIcon";
import { generatePseudonym, spliceAddress } from "../../utils/nameGenerator";
import Footer from "../Footer";
import MycelialNetwork from "../MycelialNetwork";
import FlashlightCursor from "../FlashlightCursor";
import MeshingGears from "../MeshingGears";
import ScatteredBlockchainCubes from "../ScatteredBlockchainCubes";
import PsanctuaryWatermark from "../PsanctuaryWatermark";
import {
  loadProvider,
  loadNetwork,
  loadCrowdsale,
  loadCrowdsaleStatus,
  closeCrowdsale,
  openCrowdsale,
  toggleWhitelist
} from "../../store/interactions";

const OWNER_ADDRESS = "0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266".toLowerCase();

export default function AdminPanel() {
  const dispatch = useDispatch();
  const { address } = useAccount();

  const provider = useSelector(s => s.provider.connection);
  const chainId = useSelector(s => s.provider.chainId);
  const crowdsale = useSelector(s => s.crowdsale.contract);
  const saleStatus = useSelector(s => s.crowdsale.saleStatus);

  const [ownerOnChain, setOwnerOnChain] = useState("");
  const [addressInput, setAddressInput] = useState("");
  const [breedingWhitelist, setBreedingWhitelist] = useState([]);
  const [loading, setLoading] = useState(false);

  const isOwner = useMemo(() => (address || "").toLowerCase() === OWNER_ADDRESS, [address]);

  useEffect(() => {
    const init = async () => {
      try {
        const p = provider || loadProvider(dispatch);
        const cId = chainId || await loadNetwork(p, dispatch);
        const sale = crowdsale || await loadCrowdsale(p, cId, dispatch);
        await loadCrowdsaleStatus(sale, dispatch);

        // Owner and whitelist list if available
        try {
          const owner = await sale.owner();
          setOwnerOnChain(owner);
        } catch {}
        // Load local breeding whitelist
        try {
          const raw = localStorage.getItem('breeding_whitelist');
          const arr = raw ? JSON.parse(raw) : [];
          setBreedingWhitelist(Array.from(new Set(arr)));
        } catch {}
      } catch (e) {
        console.error("Admin init error:", e);
      }
    };
    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!isOwner) {
    return (
      <div className="page-container">
        <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} className="page-content">
          <h1 className="page-title">Admin Panel</h1>
          <div className="info-box" style={{ maxWidth: 720, margin: "20px auto" }}>
            <p style={{ margin: 0 }}>
              Access Denied. Connect with the owner wallet to manage the crowdsale.
            </p>
          </div>
        </motion.div>
      </div>
    );
  }

  const handleClose = async () => {
    try {
      setLoading(true);
      await closeCrowdsale(provider, crowdsale);
      await loadCrowdsaleStatus(crowdsale, dispatch);
    } catch (e) {
      console.error(e);
      alert("Failed to close crowdsale");
    } finally { setLoading(false); }
  };

  const handleOpen = async () => {
    try {
      setLoading(true);
      await openCrowdsale(provider, crowdsale);
      await loadCrowdsaleStatus(crowdsale, dispatch);
    } catch (e) {
      console.error(e);
      alert("Failed to open crowdsale");
    } finally { setLoading(false); }
  };
  const handleDisableCrowdsaleWhitelist = async () => {
    try {
      setLoading(true);
      await toggleWhitelist(provider, crowdsale, false);
      await loadCrowdsaleStatus(crowdsale, dispatch);
    } catch (e) {
      console.error(e);
      alert('Failed to disable crowdsale whitelist');
    } finally { setLoading(false); }
  };



  const handleAdd = () => {
    try {
      setLoading(true);
      const addr = (addressInput || '').trim();
      if (!addr) return;
      const raw = localStorage.getItem('breeding_whitelist');
      const arr = raw ? JSON.parse(raw) : [];
      if (!arr.includes(addr)) arr.push(addr);
      localStorage.setItem('breeding_whitelist', JSON.stringify(arr));
      setBreedingWhitelist(Array.from(new Set(arr)));
      setAddressInput('');
    } catch (e) {
      console.error(e);
      alert('Failed to add address');
    } finally { setLoading(false); }
  };

  const handleRemove = (addr) => {
    const addressToRemove = (addr || addressInput || '').trim();
    if (!addressToRemove) return;
    try {
      setLoading(true);
      const raw = localStorage.getItem('breeding_whitelist');
      const arr = raw ? JSON.parse(raw) : [];
      const next = arr.filter(a => a.toLowerCase() !== addressToRemove.toLowerCase());
      localStorage.setItem('breeding_whitelist', JSON.stringify(next));
      setBreedingWhitelist(Array.from(new Set(next)));
      setAddressInput('');
    } catch (e) {
      console.error(e);
      alert('Failed to remove address');
    } finally { setLoading(false); }
  };

  return (
    <div className="page-container" style={{
      position: 'relative',
      background: 'linear-gradient(rgba(0, 0, 0, 0.85), rgba(0, 0, 0, 0.85))',
      minHeight: '100vh'
    }}>
      <FlashlightCursor />
      <PsanctuaryWatermark opacity={0.14} size={800} />
      {/* Multiple meshing gears animation */}
      <MeshingGears />
      <ScatteredBlockchainCubes />
      <MycelialNetwork sourceId="admin-title" />
      <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} className="page-content" style={{ position: 'relative', zIndex: 2 }}>
        <div id="admin-title">
          <MycelialTitle icon={GearIcon} title="Admin Panel" size={72} />
        </div>

        <div className="features-grid" style={{ marginTop: 20 }}>
              {saleStatus?.whitelistEnabled && (
                <div className="info-box" style={{ marginTop: 12 }}>
                  <p style={{ margin: 0, color: '#d1d5db' }}>
                    Crowdsale whitelist is currently enabled. To open the sale to everyone, disable it below.
                  </p>
                  <div style={{ marginTop: 8 }}>
                    <Button onClick={handleDisableCrowdsaleWhitelist} disabled={loading}>Disable Crowdsale Whitelist</Button>
                  </div>
                </div>
              )}

          <Card className="feature-card">
            <CardContent>
              <h3 className="feature-title">Sale Controls</h3>
              <p className="feature-description">Status: {saleStatus?.isOpen ? 'Open' : 'Closed'}</p>
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                <Button onClick={handleClose} disabled={loading || !saleStatus?.isOpen}>
                  <PauseCircle size={16} style={{ marginRight: 6 }}/> Close Sale
                </Button>
                <Button onClick={handleOpen} disabled={loading || saleStatus?.isOpen}>
                  <PlayCircle size={16} style={{ marginRight: 6 }}/> Open Sale
                </Button>
              </div>
            </CardContent>
          </Card>

          <Card className="feature-card">
            <CardContent>
              <h3 className="feature-title">Breeding Whitelist (Local)</h3>
              <div style={{ display: 'grid', gap: 8 }}>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  <input value={addressInput} onChange={e => setAddressInput(e.target.value)} placeholder="0x..." style={{ flex: 1, padding: 10, borderRadius: 8, border: '1px solid rgba(124,58,237,0.5)', background: 'rgba(0,0,0,0.3)', color: 'white' }}/>
                  <Button onClick={handleAdd}><UserPlus size={16} style={{ marginRight: 6 }}/>Add</Button>
                  <Button onClick={() => handleRemove()}><UserMinus size={16} style={{ marginRight: 6 }}/>Remove</Button>
                </div>
                <div style={{ marginTop: 8 }}>
                  <h4 className="feature-title" style={{ display: 'flex', alignItems: 'center', gap: 8 }}><ListCheck size={18}/> Whitelisted Addresses ({breedingWhitelist.length})</h4>
                  <div style={{ maxHeight: 220, overflowY: 'auto', padding: 10, border: '1px solid rgba(124,58,237,0.3)', borderRadius: 8 }}>
                    {breedingWhitelist.length === 0 && <p className="feature-description" style={{ margin: 0 }}>No addresses whitelisted yet</p>}
                    {breedingWhitelist.map((addr) => (
                      <div key={addr} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8, padding: '6px 0', borderBottom: '1px dashed rgba(124,58,237,0.2)' }}>
                        <div>
                          <div style={{ fontWeight: 600, color: '#fbbf24' }}>{generatePseudonym(addr)}</div>
                          <small style={{ color: '#9ca3af' }}>{spliceAddress(addr)}</small>
                        </div>
                        <Button onClick={() => handleRemove(addr)} size="sm"><UserMinus size={14} style={{ marginRight: 6 }}/>Remove</Button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card className="feature-card">
            <CardContent>
              <h3 className="feature-title">Contract Info</h3>
              <div className="info-box">
                <strong>Owner (on-chain):</strong><br/>
                <span style={{ fontSize: '0.875rem', color: '#a78bfa', wordBreak: 'break-all' }}>
                  {ownerOnChain || 'Loading...'}
                </span>
              </div>
              <p className="feature-description" style={{ marginTop: '16px', fontSize: '0.875rem', color: '#9ca3af' }}>
                💡 Sale statistics have been moved to the Donate page for public visibility.
              </p>
            </CardContent>
          </Card>
        </div>

        <Footer />
      </motion.div>
    </div>
  );
}

