import React, { useState, useEffect } from "react";
import { Droplets, Sparkles } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

/**
 * MushroomFarm - Interactive mushroom growing mechanic
 * - One daily mushroom to collect
 * - Mist every 8 hours to grow additional mushrooms
 * - Animated SVG mushroom that grows when misted
 */
export default function MushroomFarm() {
  const [lastMistTime, setLastMistTime] = useState(null);
  const [lastCollectTime, setLastCollectTime] = useState(null);
  const [mushroomGrowth, setMushroomGrowth] = useState(0);
  const [mushroomsCollected, setMushroomsCollected] = useState(0);
  const [showTooltip, setShowTooltip] = useState(false);
  const [waterDroplets, setWaterDroplets] = useState([]);

  // Load from localStorage
  useEffect(() => {
    const savedMistTime = localStorage.getItem('lastMistTime');
    const savedCollectTime = localStorage.getItem('lastCollectTime');
    const savedGrowth = localStorage.getItem('mushroomGrowth');
    const savedCollected = localStorage.getItem('mushroomsCollected');
    
    if (savedMistTime) setLastMistTime(parseInt(savedMistTime));
    if (savedCollectTime) setLastCollectTime(parseInt(savedCollectTime));
    if (savedGrowth) setMushroomGrowth(parseFloat(savedGrowth));
    if (savedCollected) setMushroomsCollected(parseInt(savedCollected));
  }, []);

  // Check if can mist (every 8 hours)
  const canMist = () => {
    if (!lastMistTime) return true;
    const eightHours = 8 * 60 * 60 * 1000;
    return Date.now() - lastMistTime >= eightHours;
  };

  // Check if can collect daily mushroom
  const canCollectDaily = () => {
    if (!lastCollectTime) return true;
    const oneDay = 24 * 60 * 60 * 1000;
    return Date.now() - lastCollectTime >= oneDay;
  };

  // Time until next mist
  const getTimeUntilNextMist = () => {
    if (!lastMistTime) return "Ready now!";
    const eightHours = 8 * 60 * 60 * 1000;
    const timeLeft = eightHours - (Date.now() - lastMistTime);
    if (timeLeft <= 0) return "Ready now!";
    
    const hours = Math.floor(timeLeft / (60 * 60 * 1000));
    const minutes = Math.floor((timeLeft % (60 * 60 * 1000)) / (60 * 1000));
    return `${hours}h ${minutes}m`;
  };

  // Handle misting
  const handleMist = () => {
    if (!canMist()) return;
    
    const now = Date.now();
    setLastMistTime(now);
    localStorage.setItem('lastMistTime', now.toString());
    
    // Grow mushroom
    const newGrowth = Math.min(mushroomGrowth + 0.25, 1);
    setMushroomGrowth(newGrowth);
    localStorage.setItem('mushroomGrowth', newGrowth.toString());
    
    // Create water droplet animation
    const droplets = Array.from({ length: 15 }, (_, i) => ({
      id: Math.random(),
      x: Math.random() * 100,
      delay: Math.random() * 0.3
    }));
    setWaterDroplets(droplets);
    setTimeout(() => setWaterDroplets([]), 2000);
  };

  // Handle collecting mushroom
  const handleCollect = () => {
    if (mushroomGrowth < 1) return;
    
    const newCount = mushroomsCollected + 1;
    setMushroomsCollected(newCount);
    localStorage.setItem('mushroomsCollected', newCount.toString());
    
    // Reset growth
    setMushroomGrowth(0);
    localStorage.setItem('mushroomGrowth', '0');
  };

  // Handle daily collection
  const handleDailyCollect = () => {
    if (!canCollectDaily()) return;
    
    const now = Date.now();
    setLastCollectTime(now);
    localStorage.setItem('lastCollectTime', now.toString());
    
    const newCount = mushroomsCollected + 1;
    setMushroomsCollected(newCount);
    localStorage.setItem('mushroomsCollected', newCount.toString());
  };

  return (
    <div id="mushroom-farm" className="mushroom-farm" style={{
      background: 'linear-gradient(135deg, rgba(124, 58, 237, 0.1), rgba(236, 72, 153, 0.1))',
      borderRadius: '16px',
      padding: '32px',
      border: '1px solid rgba(124, 58, 237, 0.3)',
      position: 'relative',
      overflow: 'hidden'
    }}>
      <h3 style={{
        fontSize: '1.5rem',
        marginBottom: '24px',
        display: 'flex',
        alignItems: 'center',
        gap: 8,
        color: '#a78bfa'
      }}>
        <svg width="120" height="120" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
          {/* Animated grow-to-harvest cycle - MUCH BIGGER */}
          <g style={{ animation: 'growCycle 4s ease-in-out infinite' }}>
            {/* Spore/Seed */}
            <circle cx="20" cy="80" r="3" fill="#7c3aed" opacity="0.8">
              <animate attributeName="opacity" values="0.8;0.3;0.8" dur="4s" repeatCount="indefinite" />
            </circle>

            {/* Sprout */}
            <line x1="35" y1="80" x2="35" y2="70" stroke="#22c55e" strokeWidth="2">
              <animate attributeName="y2" values="80;70;80" dur="4s" repeatCount="indefinite" />
            </line>
            <circle cx="35" cy="70" r="2" fill="#22c55e">
              <animate attributeName="r" values="0;2;0" dur="4s" repeatCount="indefinite" />
            </circle>

            {/* Growing mushroom */}
            <rect x="47" y="65" width="6" height="15" rx="1" fill="#fbbf24">
              <animate attributeName="height" values="5;15;5" dur="4s" repeatCount="indefinite" />
              <animate attributeName="y" values="75;65;75" dur="4s" repeatCount="indefinite" />
            </rect>
            <path d="M 50 55 Q 45 57, 44 62 Q 44 65, 47 66 L 53 66 Q 56 65, 56 62 Q 55 57, 50 55 Z" fill="#ec4899">
              <animate attributeName="opacity" values="0;1;0" dur="4s" repeatCount="indefinite" />
            </path>

            {/* Mature mushroom */}
            <rect x="67" y="55" width="8" height="25" rx="2" fill="#a78bfa" />
            <path d="M 71 35 Q 63 38, 62 45 Q 62 50, 67 53 L 75 53 Q 80 50, 80 45 Q 79 38, 71 35 Z" fill="#7c3aed" />
            <ellipse cx="68" cy="42" rx="2" ry="3" fill="#fbbf24" opacity="0.8" />

            {/* Harvest sparkle */}
            <g opacity="0.8">
              <line x1="85" y1="40" x2="90" y2="35" stroke="#fbbf24" strokeWidth="2">
                <animate attributeName="opacity" values="0;1;0" dur="4s" repeatCount="indefinite" begin="3s" />
              </line>
              <line x1="90" y1="40" x2="85" y2="35" stroke="#fbbf24" strokeWidth="2">
                <animate attributeName="opacity" values="0;1;0" dur="4s" repeatCount="indefinite" begin="3s" />
              </line>
            </g>
          </g>
        </svg>
        Mushroom Farm
      </h3>

      <div style={{ display: 'flex', gap: '32px', flexWrap: 'wrap', alignItems: 'center' }}>
        {/* Mushroom Growing Area */}
        <div style={{ flex: 1, minWidth: '250px', textAlign: 'center', position: 'relative' }}>
          <div 
            style={{ position: 'relative', display: 'inline-block', cursor: canMist() ? 'pointer' : 'not-allowed' }}
            onClick={handleMist}
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
          >
            {/* Animated SVG Mushroom */}
            <motion.svg
              width="200"
              height="200"
              viewBox="0 0 100 100"
              animate={{
                scale: [1, 1.05, 1],
                rotate: [0, 2, -2, 0]
              }}
              transition={{
                duration: 3,
                repeat: Infinity,
                ease: "easeInOut"
              }}
            >
              {/* Stem */}
              <motion.rect
                x="42"
                y="50"
                width="16"
                height={30 * mushroomGrowth}
                rx="8"
                fill="url(#stemGradient)"
                initial={{ height: 0 }}
                animate={{ height: 30 * mushroomGrowth }}
                transition={{ duration: 0.8, ease: "easeOut" }}
              />
              
              {/* Cap */}
              <motion.ellipse
                cx="50"
                cy="50"
                rx={25 * mushroomGrowth}
                ry={15 * mushroomGrowth}
                fill="url(#capGradient)"
                initial={{ rx: 0, ry: 0 }}
                animate={{ rx: 25 * mushroomGrowth, ry: 15 * mushroomGrowth }}
                transition={{ duration: 0.8, ease: "easeOut" }}
              />
              
              {/* Spots */}
              {mushroomGrowth > 0.3 && (
                <>
                  <motion.circle cx="40" cy="48" r={3 * mushroomGrowth} fill="rgba(255, 255, 255, 0.8)" 
                    initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 0.3 }} />
                  <motion.circle cx="55" cy="45" r={2.5 * mushroomGrowth} fill="rgba(255, 255, 255, 0.8)"
                    initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 0.4 }} />
                  <motion.circle cx="48" cy="52" r={2 * mushroomGrowth} fill="rgba(255, 255, 255, 0.8)"
                    initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 0.5 }} />
                </>
              )}
              
              {/* Gradients */}
              <defs>
                <linearGradient id="capGradient" x1="0%" y1="0%" x2="0%" y2="100%">
                  <stop offset="0%" stopColor="#7c3aed" />
                  <stop offset="50%" stopColor="#a78bfa" />
                  <stop offset="100%" stopColor="#ec4899" />
                </linearGradient>
                <linearGradient id="stemGradient" x1="0%" y1="0%" x2="0%" y2="100%">
                  <stop offset="0%" stopColor="#fbbf24" />
                  <stop offset="100%" stopColor="#f59e0b" />
                </linearGradient>
              </defs>
            </motion.svg>

            {/* Water Droplets Animation */}
            <AnimatePresence>
              {waterDroplets.map(drop => (
                <motion.div
                  key={drop.id}
                  initial={{ y: -20, x: `${drop.x}%`, opacity: 1, scale: 1 }}
                  animate={{ y: 100, opacity: 0, scale: 0.5 }}
                  exit={{ opacity: 0 }}
                  transition={{ duration: 1.5, delay: drop.delay }}
                  style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    pointerEvents: 'none'
                  }}
                >
                  <Droplets size={16} style={{ color: '#3b82f6' }} />
                </motion.div>
              ))}
            </AnimatePresence>

            {/* Tooltip */}
            {showTooltip && (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                style={{
                  position: 'absolute',
                  top: '-60px',
                  left: '50%',
                  transform: 'translateX(-50%)',
                  background: 'rgba(0, 0, 0, 0.9)',
                  color: '#fbbf24',
                  padding: '8px 12px',
                  borderRadius: '8px',
                  fontSize: '0.875rem',
                  whiteSpace: 'nowrap',
                  border: '1px solid rgba(251, 191, 36, 0.5)',
                  zIndex: 10
                }}
              >
                {canMist() ? '💧 Click to mist!' : `⏰ Next mist: ${getTimeUntilNextMist()}`}
              </motion.div>
            )}
          </div>

          <div style={{ marginTop: '16px', fontSize: '0.875rem', color: '#9ca3af' }}>
            Growth: {Math.round(mushroomGrowth * 100)}%
          </div>
        </div>

        {/* Stats & Actions */}
        <div style={{ flex: 1, minWidth: '250px' }}>
          <div style={{ marginBottom: '24px' }}>
            <div style={{ fontSize: '2rem', fontWeight: 'bold', color: '#fbbf24', display: 'flex', alignItems: 'center', gap: '8px', justifyContent: 'center' }}>
              {mushroomsCollected}
              <svg width="80" height="80" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
                <ellipse cx="50" cy="85" rx="25" ry="8" fill="#7c3aed" opacity="0.3" />
                <rect x="42" y="50" width="16" height="35" rx="3" fill="#fbbf24" />
                <path
                  d="M 50 20 Q 30 25, 25 40 Q 25 50, 35 55 L 65 55 Q 75 50, 75 40 Q 70 25, 50 20 Z"
                  fill="#ec4899"
                />
                <ellipse cx="40" cy="35" rx="4" ry="6" fill="#fbbf24" opacity="0.8" />
                <ellipse cx="55" cy="32" rx="3" ry="5" fill="#fbbf24" opacity="0.8" />
                <ellipse cx="48" cy="40" rx="2" ry="3" fill="#fbbf24" opacity="0.8" />
              </svg>
            </div>
            <div style={{ fontSize: '0.875rem', color: '#9ca3af' }}>
              Mushrooms Collected
            </div>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <button
              onClick={handleDailyCollect}
              disabled={!canCollectDaily()}
              style={{
                padding: '12px 24px',
                background: canCollectDaily() 
                  ? 'linear-gradient(135deg, #7c3aed, #ec4899)' 
                  : 'rgba(124, 58, 237, 0.3)',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                cursor: canCollectDaily() ? 'pointer' : 'not-allowed',
                fontSize: '1rem',
                fontWeight: 'bold',
                transition: 'all 0.3s'
              }}
            >
              {canCollectDaily() ? '✨ Collect Daily Mushroom' : '⏰ Come back tomorrow'}
            </button>

            <button
              onClick={handleCollect}
              disabled={mushroomGrowth < 1}
              style={{
                padding: '12px 24px',
                background: mushroomGrowth >= 1
                  ? 'linear-gradient(135deg, #22c55e, #10b981)'
                  : 'rgba(34, 197, 94, 0.3)',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                cursor: mushroomGrowth >= 1 ? 'pointer' : 'not-allowed',
                fontSize: '1rem',
                fontWeight: 'bold',
                transition: 'all 0.3s'
              }}
            >
              {mushroomGrowth >= 1 ? '🍄 Harvest Mushroom' : '🌱 Keep growing...'}
            </button>
          </div>

          <div style={{ marginTop: '16px', fontSize: '0.75rem', color: '#6b7280', lineHeight: '1.5' }}>
            💡 Mist your mushroom every 8 hours to help it grow. Once fully grown, harvest it!
          </div>
        </div>
      </div>
    </div>
  );
}

